let ascii_isupper c =
  u32_sub (to_u32 c) (Char.code 'A') < 26

let ascii_islower c =
  u32_sub (to_u32 c) (Char.code 'a') < 26

let ascii_isdigit c =
  u32_sub (to_u32 c) (Char.code '0') < 10

let musl_memcpy ed dest src n =
  mem_copy ed dest src n;
  dest

let musl_memmove ed dest src n =
  mem_copy ed dest src n;
  dest

let musl_memset ed dest c n =
  mem_fill ed dest (to_u8 c) n;
  dest

let musl_memcmp ed vl vr n =
  let rec loop1 n l r =
    if n <> 0 && ld_u8 ed l = ld_u8 ed r then
      loop1 (n - 1) (l + 1) (r + 1)
    else if n = 0 then 0 else ld_u8 ed l - ld_u8 ed r
  in
  loop1 n vl vr

let musl_strlen ed s =
  let a = s in
  let rec loop1 s =
    if ld_s8 ed s = 0 then s - a else loop1 (s + 1)
  in
  loop1 s

let musl_strcpy ed dest src =
  let rec loop1 src d =
    st_s8 ed d (ld_s8 ed src);
    if ld_s8 ed d = 0 then dest else loop1 (src + 1) (d + 1)
  in
  loop1 src dest

let musl_strncpy ed dest src n =
  let rec loop1 src n d =
    if n <> 0 && ld_s8 ed src <> 0 then
      (st_s8 ed d (ld_s8 ed src);
       loop1 (src + 1) (n - 1) (d + 1))
    else
      let rec loop3 n d =
        if n = 0 then
          dest
        else
          (st_s8 ed d 0;
           loop3 (n - 1) (d + 1))
      in
      loop3 n d
  in
  loop1 src n dest

let musl_strcat ed dest src =
  ignore (musl_strcpy ed (dest + musl_strlen ed dest) src);
  dest

let musl_strcmp ed l r =
  let rec loop1 l r =
    if ld_s8 ed l = ld_s8 ed r && ld_s8 ed l <> 0 then
      loop1 (l + 1) (r + 1)
    else
      ld_u8 ed l - ld_u8 ed r
  in
  loop1 l r

let musl_strncmp ed ls rs n =
  if n = 0 then
    0
  else
    let rec loop2 n l r =
      if ld_u8 ed l <> 0 && ld_u8 ed r <> 0 && n <> 0 && ld_u8 ed l = ld_u8 ed r then
        loop2 (n - 1) (l + 1) (r + 1)
      else
        ld_u8 ed l - ld_u8 ed r
    in
    loop2 (n - 1) ls rs

let musl_strcasecmp ed ls rs =
  let rec loop1 l r =
    if ld_u8 ed l <> 0 &&
       ld_u8 ed r <> 0 &&
       (let r1 = if ascii_isupper (ld_u8 ed l) then ld_u8 ed l lor 32 else ld_u8 ed l in
        r1 = (if ascii_isupper (ld_u8 ed r) then ld_u8 ed r lor 32 else ld_u8 ed r)) then
      loop1 (l + 1) (r + 1)
    else
      let r2 = if ascii_isupper (ld_u8 ed l) then ld_u8 ed l lor 32 else ld_u8 ed l in
      r2 - (if ascii_isupper (ld_u8 ed r) then ld_u8 ed r lor 32 else ld_u8 ed r)
  in
  loop1 ls rs

let musl_strncasecmp ed ls rs n =
  if n = 0 then
    0
  else
    let rec loop2 n l r =
      if ld_u8 ed l <> 0 &&
         ld_u8 ed r <> 0 &&
         n <> 0 &&
         (let r1 = if ascii_isupper (ld_u8 ed l) then ld_u8 ed l lor 32 else ld_u8 ed l in
          r1 = (if ascii_isupper (ld_u8 ed r) then ld_u8 ed r lor 32 else ld_u8 ed r)) then
        loop2 (n - 1) (l + 1) (r + 1)
      else
        let r2 = if ascii_isupper (ld_u8 ed l) then ld_u8 ed l lor 32 else ld_u8 ed l in
        r2 - (if ascii_isupper (ld_u8 ed r) then ld_u8 ed r lor 32 else ld_u8 ed r)
    in
    loop2 (n - 1) ls rs

let musl_strchr ed s c =
  let ch_ = to_u8 c in
  let rec loop1 s =
    if ld_s8 ed s <> 0 && ld_u8 ed s <> ch_ then
      loop1 (s + 1)
    else if ld_u8 ed s = ch_ then s else 0
  in
  loop1 s

let musl_strstr ed h n =
  if ld_s8 ed n = 0 then
    h
  else
    let rec loop2 h =
      if ld_s8 ed h = 0 then
        0
      else
        let rec loop5 i =
          if ld_s8 ed (n + i) <> 0 && ld_s8 ed (h + i) = ld_s8 ed (n + i) then
            loop5 (i + 1)
          else if ld_s8 ed (n + i) = 0 then h else loop2 (h + 1)
        in
        loop5 0
    in
    loop2 h

