    if ld_s8 ed s = 0 then
      0
    else
      let rec loop4 c =
        if ld_s8 ed c = 0 then
          loop1 (s + 1)
        else if ld_s8 ed s = ld_s8 ed c then s else loop4 (c + 1)
      in
      loop4 b
  in
  loop1 s

let musl_isdigit c =
  ascii_isdigit c

let musl_isalpha c =
  u32_sub (to_u32 c lor 32) (Char.code 'a') < 26

let musl_isupper c =
  ascii_isupper c

let musl_islower c =
  ascii_islower c

let musl_isgraph c =
  u32_sub (to_u32 c) 33 < 94

let musl_isspace c =
  u32_sub (to_u32 c) (Char.code '\t') < 5 || c = Char.code ' '

let musl_isalnum c =
  musl_isalpha c || musl_isdigit c

let musl_iscntrl c =
  to_u32 c < 32 || c = 127

let musl_ispunct c =
  musl_isgraph c && not (musl_isalnum c)

let musl_tolower c =
  if musl_isupper c then c lor 32 else c

let musl_toupper c =
  if musl_islower c then c land 95 else c

let musl_atoi ed s =
  let rec loop7 s n neg =
    if musl_isdigit (ld_s8 ed s) then
      loop7 (s + 1) (10 * n - (ld_s8 ed s - Char.code '0')) neg
    else if neg = 0 then -n else n
  in
  let rec loop1 s =
    if musl_isspace (ld_s8 ed s) then
      loop1 (s + 1)
    else
      match ld_s8 ed s with
      | 45 (* '-' *) -> loop7 (s + 1) 0 1
      | 43 (* '+' *) -> loop7 (s + 1) 0 0
      | _ -> loop7 s 0 0
  in
  loop1 s

let musl_atol ed s =
  let rec loop7 s n neg =
    if musl_isdigit (ld_s8 ed s) then
      loop7 (s + 1) (10 * n - (ld_s8 ed s - Char.code '0')) neg
    else if neg = 0 then -n else n
  in
  let rec loop1 s =
    if musl_isspace (ld_s8 ed s) then
      loop1 (s + 1)
    else
      match ld_s8 ed s with
      | 45 (* '-' *) -> loop7 (s + 1) 0 1
      | 43 (* '+' *) -> loop7 (s + 1) 0 0
      | _ -> loop7 s 0 0
  in
  loop1 s

let musl_strtol ed s end_' base =
  let join6 p n neg any' over =
    let lim = max_int + neg in
    let rec loop7 p n any' over =
      let join12 n =
        if neg = 0 then n else -n
      in
      if base = 10 && musl_isdigit (ld_s8 ed p) then
        (let t1 = p in
         let p = p + 1 in
         let d = ld_s8 ed t1 - Char.code '0' in
         if over <> 0 || u64_gt n (u64_div (lim - d) 10) then
           loop7 p n 1 1
         else
           loop7 p (10 * n + d) 1 over)
      else
        (if end_' <> 0 then st_ptr ed end_' (if any' = 0 then s else p);
         if over = 0 then join12 n else join12 lim)
    in
    loop7 p n any' over
  in
  let rec loop1 p =
    if musl_isspace (ld_s8 ed p) then
      loop1 (p + 1)
    else
      match ld_s8 ed p with
      | 45 (* '-' *) -> join6 (p + 1) 0 1 0 0
      | 43 (* '+' *) -> join6 (p + 1) 0 0 0 0
      | _ -> join6 p 0 0 0 0
  in
  loop1 s

