  else
    let curr = Buffheader_T.bh_first_b_next ed buf in
    let c = ld_u8 ed (Buffblock_T.b_str ed curr + Buffheader_T.bh_index ed buf) in
    if advance then
      (Buffheader_T.set_bh_index ed buf (Buffheader_T.bh_index ed buf + 1);
       if ld_u8 ed (Buffblock_T.b_str ed curr + Buffheader_T.bh_index ed buf) = nul then
         (Buffheader_T.set_bh_first_b_next ed buf (Buffblock_T.b_next ed curr);
          Buffheader_T.set_bh_index ed buf 0));
    c

