let fix_input_buffer ed buf len =
  let rec loop1 len i p =
    let i = i - 1 in
    let join5 len p =
      loop1 len i (p + 1)
    in
    if i >= 0 then
      (if ld_u8 ed p = nul ||
          ld_u8 ed p = 128 &&
          (i < 2 ||
           ld_u8 ed (p + 1) <> ks_extra ||
           ld_u8 ed (p + 2) <> 96 && ld_u8 ed (p + 2) <> 110) then
         (ignore (musl_memmove ed (p + 3) (p + 1) i);
          st_u8 ed (p + 2)
            (to_u8
               (if ld_u8 ed p = 128 || ld_u8 ed p = nul then
                  Char.code 'X'
                else
                  to_u32 (- ld_u8 ed p) lsr 8 land 255));
          st_u8 ed (p + 1)
            (to_u8
               (match ld_u8 ed p with
                | 128 -> ks_special
                | 0 (* NUL *) -> ks_zero
                | _ -> - ld_u8 ed p land 255));
          st_u8 ed p 128;
          join5 (len + 2) (p + 2))
       else
         join5 len p)
    else
      (st_u8 ed p nul;
       len)
  in
  loop1 len len buf

