  st_u8 ed (out_buf + t1) (to_u8 (to_u32 c));
  if ed.st.out_pos >= out_size then out_flush ed;
  to_i32 (to_u32 c)

let out_str ed s =
  if not (s = 0 || ld_u8 ed s = nul) then
    (if ed.st.out_pos > 8111 then out_flush ed;
     let rec loop4 s =
       if ld_u8 ed s = 0 then
         (if p_wd ed <> 0 then out_flush ed)
       else
         (ignore (out_char_nf ed (ld_u8 ed s));
          loop4 (s + 1))
