let utf_ptr2char_and_len ed p =
  if ld_u8 ed p < 128 then
    (let lenp = if ld_u8 ed p = nul then 0 else 1 in
     let out___r__ = ld_u8 ed p in
     (out___r__, lenp))
  else
    let len = ld_s8 ed (utf8len_tab_zero + ld_u8 ed p) in
    if len <= 1 || ld_u8 ed (p + 1) land 192 <> 128 then
      (let out___r__ = ld_u8 ed p in
       (out___r__, 1))
    else
      let c = i32_shl (ld_u8 ed p land 31) 6 + ld_u8 ed (p + 1) land 63 in
      if len = 2 then
        (c, 2)
      else if ld_u8 ed (p + 2) land 192 = 128 then
        (let c =
           i32_shl (ld_u8 ed p land 15) 12 + i32_shl (ld_u8 ed (p + 1) land 63) 6 +
           ld_u8 ed (p + 2) land 63
         in
         if len = 3 then
           (c, 3)
         else if ld_u8 ed (p + 3) land 192 = 128 then
           (let c =
              i32_shl (ld_u8 ed p land 7) 18 + i32_shl (ld_u8 ed (p + 1) land 63) 12 +
              i32_shl (ld_u8 ed (p + 2) land 63) 6 +
              ld_u8 ed (p + 3) land 63
            in
            if len = 4 then
              (c, 4)
            else if ld_u8 ed (p + 4) land 192 = 128 then
              (let c =
                 i32_shl (ld_u8 ed p land 3) 24 + i32_shl (ld_u8 ed (p + 1) land 63) 18 +
                 i32_shl (ld_u8 ed (p + 2) land 63) 12 +
                 i32_shl (ld_u8 ed (p + 3) land 63) 6 +
                 ld_u8 ed (p + 4) land 63
               in
               if len = 5 then
                 (c, 5)
               else if ld_u8 ed (p + 5) land 192 = 128 then
                 (let out___r__ =
                    i32_shl (ld_u8 ed p land 1) 30 + i32_shl (ld_u8 ed (p + 1) land 63) 24 +
                    i32_shl (ld_u8 ed (p + 2) land 63) 18 +
                    i32_shl (ld_u8 ed (p + 3) land 63) 12 +
                    i32_shl (ld_u8 ed (p + 4) land 63) 6 +
                    ld_u8 ed (p + 5) land 63
                  in
                  (out___r__, 6))
               else
                 let out___r__ = ld_u8 ed p in
                 (out___r__, 1))
            else
              let out___r__ = ld_u8 ed p in
              (out___r__, 1))
         else
           let out___r__ = ld_u8 ed p in
           (out___r__, 1))
      else
        let out___r__ = ld_u8 ed p in
        (out___r__, 1)

let utf_ptr2char ed p =
  let (r1, _r2) = utf_ptr2char_and_len ed p in
