let intable ed table size c =
  if c < Interval.first ed table then
    false
  else
    let rec loop2 bot top =
      if top >= bot then
        (let mid = (bot + top) / 2 in
         if Interval.last ed (table + mid * 16) < c then
           loop2 (mid + 1) top
         else if Interval.first ed (table + mid * 16) > c then loop2 bot (mid - 1) else true)
      else
        false
    in
    loop2 0 (to_i32 (u64_div size 16 - 1))

let utf_iscomposing ed c =
  intable ed utf_iscomposing__combining 5664 c

let utf_iscomposinglike_char ed _c1 c2 =
  utf_iscomposing ed c2

let utfc_ptr2len ed p =
  let b0 = ld_u8 ed p in
  if b0 = nul then
    0
  else if b0 < 128 && ld_u8 ed (p + 1) < 128 then
    1
  else
    let (r3, r4) = utf_ptr2char_and_len ed p in
    if r4 = 1 && b0 >= 128 then
      1
    else if ld_u8 ed (p + r4) < 128 then
      r4
    else
      let (r5, r6) = utf_ptr2char_and_len ed (p + r4) in
      if utf_iscomposinglike_char ed r3 r5 then
        (let rec loop6 len cc_len _utf_ptr2char_and_len__o_r__ _utf_ptr2char_and_len__o_lenp =
           let len = len + cc_len in
           if ld_u8 ed (p + len) < 128 then
             len
           else
             let (r1, r2) = utf_ptr2char_and_len ed (p + len) in
             if utf_iscomposing ed r1 then loop6 len r2 r1 r2 else len
         in
         loop6 r4 r6 r5 r6)
      else
        r4

let vim_strbyte ed string_ c =
  if c <= 0 || c > 255 then 0 else musl_strchr ed string_ c

let vim_strchr ed string_ c =
  if c > 0 && c < 128 then
    vim_strbyte ed string_ c
  else if c >= 128 then
    (let rec loop9 p =
       if ld_u8 ed p = nul then
         0
       else
         let l = utfc_ptr2len ed p in
         if utf_ptr2char ed p = c && l > 1 then p else loop9 (p + l)
     in
     loop9 string_)
  else
    let rec loop3 p =
      let b = ld_u8 ed p in
      if b = nul then 0 else if b = c then p else loop3 (p + utfc_ptr2len ed p)
    in
    loop3 string_

