     else if intable ed utf_char2cells__doublewidth 1952 c then
       2
     else if p_emoji ed <> 0 && intable ed utf_char2cells__emoji_wide 864 c then 2 else join6 ())
  else if c >= 128 && not (vim_isprintc ed c) then 4 else join6 ()

let rec char2cells ed c =
  if c < 0 then
    char2cells ed
      (match c with
       | 128 -> ks_special
       | 0 (* NUL *) -> ks_zero
       | _ -> -c land 255) +
    2
  else if c >= 128 then utf_char2cells ed c else ld_u8 ed (g_chartab + c land 255) land ct_cell_mask

let utf_ptr2cells ed p =
  if ld_u8 ed p >= 128 then
    (let (r1, r2) = utf_ptr2char_and_len ed p in
     if r2 = 1 || r1 = nul then
       4
     else if r1 < 128 then
       (if vim_isprintc ed r1 then char2cells ed r1 else 4)
     else
       utf_char2cells ed r1)
  else
    1

let ptr2cells ed p =
  if ld_u8 ed p >= 128 then
    utf_ptr2cells ed p
  else
    ld_u8 ed (g_chartab + ld_u8 ed p) land ct_cell_mask

