  vim_strnsize ed s 2147483647

let redraw_win_later ed wp type_ =
  if not ed.st.exiting && not ed.st.redraw_not_allowed && Win_T.w_redr_type ed wp < type_ then
    (Win_T.set_w_redr_type ed wp type_;
     if type_ >= upd_not_valid then Win_T.set_w_lines_valid ed wp 0;
     if ed.st.must_redraw < type_ then ed.st.must_redraw <- type_)

let redraw_later ed type_ =
  redraw_win_later ed ed.st.curwin type_

let set_must_redraw ed type_ =
  if not ed.st.redraw_not_allowed && ed.st.must_redraw < type_ then ed.st.must_redraw <- type_

let stuff_empty ed =
  Buffheader_T.bh_first_b_next ed readbuf1 = 0 && Buffheader_T.bh_first_b_next ed readbuf2 = 0

let can_get_old_char ed =
  ed.st.old_char <> -1 && (ed.st.old_KeyStuffed || stuff_empty ed)

let init_chartabsize_arg _ed cts wp _lnum col line ptr =
  Chartabsize_T.clear cts;
  cts.cts_win <- wp;
  cts.cts_vcol <- col;
  cts.cts_line <- line;
  cts.cts_ptr <- ptr

let win_col_off ed wp =
  if Win_T.w_onebuf_opt_wo_nu ed wp <> 0 || Win_T.w_onebuf_opt_wo_rnu ed wp <> 0 then 8 else 0

let win_col_off2 ed wp =
  if (Win_T.w_onebuf_opt_wo_nu ed wp <> 0 || Win_T.w_onebuf_opt_wo_rnu ed wp <> 0) &&
     vim_strchr ed (p_cpo ed) cpo_numcol <> 0 then
    8
  else
    0

let in_win_border ed wp vcol =
  if Win_T.w_width ed wp = 0 then
    false
  else
    let r1 = Win_T.w_width ed wp in
    let width1 = r1 - win_col_off ed wp in
    if vcol < width1 - 1 then
      false
    else if vcol = width1 - 1 then
      true
    else
      let width2 = width1 + win_col_off2 ed wp in
      if width2 <= 0 then false else (vcol - width1) mod width2 = width2 - 1

let win_nolbr_chartabsize ed cts headp =
  let wp = cts.cts_win in
  let s = cts.cts_ptr in
  let col = cts.cts_vcol in
  if ld_u8 ed s = tab &&
     (Win_T.w_onebuf_opt_wo_list ed wp = 0 || Win_T.w_lcs_chars_tab1 ed wp <> 0) then
    (let n = to_i32 (Buf_T.b_p_ts ed (Win_T.w_buffer ed wp)) in
     n - col mod n)
