    if i < 232 then
      (let n = i - 16 in
       let cr = ld_s32 ed (rgb_to_cterm_idx__cube + n / 36 mod 6 * 4) in
       let cg = ld_s32 ed (rgb_to_cterm_idx__cube + n / 6 mod 6 * 4) in
       let cb = ld_s32 ed (rgb_to_cterm_idx__cube + n mod 6 * 4) in
       let d = (cr - r) * (cr - r) + (cg - g) * (cg - g) + (cb - b) * (cb - b) in
       let join10 best best_d =
         loop1 best best_d (i + 1)
       in
       if best_d < 0 || d < best_d then join10 i d else join10 best best_d)
    else
      loop3 best best_d 232
  in
