let blend_cterm_colors ed popup_c popup_rgb under_c under_rgb default_rgb blend_val =
  let fr = frame_push ed 32 in
  let pr_addr = fr + 0 in
  let pg_addr = fr + 4 in
  let pb_addr = fr + 8 in
  let ur_addr = fr + 12 in
  let ug_addr = fr + 16 in
