let findoption ed arg =
  let join25 opt_idx =
    opt_idx
  in
  let join23 opt_idx s =
    if s = 0 then join25 (-1) else join25 opt_idx
  in
  let rec loop12 opt_idx is_term_opt =
    let s = Vimoption.fullname ed (options + opt_idx * 112) in
    let join15 () =
      let join17 s =
        if s = 0 && not is_term_opt then
          (let rec loop19 opt_idx s =
             if Vimoption.fullname ed (options + opt_idx * 112) = 0 then
               join23 opt_idx s
             else
               let s = Vimoption.shortname ed (options + opt_idx * 112) in
               if s <> 0 && musl_strcmp ed arg s = 0 then
                 join23 opt_idx s
               else
                 loop19 (opt_idx + 1) 0
           in
           loop19 (ld_s16 ed (findoption__quick_tab + (ld_u8 ed arg - Char.code 'a') * 2)) s)
        else
          join23 opt_idx s
      in
      if s <> 0 && ld_s8 ed s <> ld_u8 ed arg then join17 0 else join17 s
    in
    if s <> 0 && ld_s8 ed s = ld_u8 ed arg then
      (if musl_strcmp ed arg s = 0 then join15 () else loop12 (opt_idx + 1) is_term_opt)
    else
      join15 ()
  in
  let join7 () =
    if ld_char ed arg < 'a' || ld_char ed arg > 'z' then
      -1
    else
      let is_term_opt = ld_char ed arg = 't' && ld_char ed (arg + 1) = '_' in
      if is_term_opt then
        loop12 (ld_s16 ed (findoption__quick_tab + 52)) is_term_opt
      else
        loop12 (ld_s16 ed (findoption__quick_tab + (ld_u8 ed arg - Char.code 'a') * 2)) is_term_opt
  in
  let rec loop6 opt_idx p last_opt_idx =
    if opt_idx < last_opt_idx then
      (let s = Vimoption.fullname ed (options + opt_idx * 112) in
       if ld_s8 ed s <> ld_s8 ed p then
         (if ld_s8 ed s = Char.code 't' && ld_s8 ed (s + 1) = Char.code '_' then
            st_s16 ed (findoption__quick_tab + 52) (to_i16 opt_idx)
          else
            st_s16 ed (findoption__quick_tab + (ld_s8 ed s - Char.code 'a') * 2) (to_i16 opt_idx));
       loop6 (opt_idx + 1) s last_opt_idx)
    else
      join7 ()
  in
  if ld_s16 ed (findoption__quick_tab + 2) = 0 then
    (let rec loop2 last_opt_idx =
       if Vimoption.fullname ed (options + last_opt_idx * 112) = 0 then
         (let rec loop4 tab_idx =
            if tab_idx < 27 then
              (st_s16 ed (findoption__quick_tab + tab_idx * 2) (to_i16 last_opt_idx);
               loop4 (tab_idx + 1))
            else
