let redraw_win_range_later ed wp first last =
  if last >= Win_T.w_topline ed wp && first < Win_T.w_botline ed wp then
    (if Win_T.w_redraw_top ed wp = 0 || Win_T.w_redraw_top ed wp > first then
       Win_T.set_w_redraw_top ed wp first;
     if Win_T.w_redraw_bot ed wp = 0 || Win_T.w_redraw_bot ed wp < last then
       Win_T.set_w_redraw_bot ed wp last;
     redraw_win_later ed wp upd_valid)

