let cursorcmd ed =
  if not ed.st.cmd_silent then
    (ed.st.msg_row <- ed.st.cmdline_row + Cmdline_info_T.cmdspos ed ccline / ed.st.cmdline_width;
     ed.st.msg_col <- Cmdline_info_T.cmdspos ed ccline mod ed.st.cmdline_width;
     if ed.st.msg_row >= rows ed then ed.st.msg_row <- to_i32 (rows ed - 1);
     windgoto ed ed.st.msg_row (ed.st.cmdline_col_off + ed.st.msg_col))

