  else if ed.st.t_colors = 8 then
    (let color = ld_s32 ed (color_numbers_8 + idx * 4) in
     let join16 boldp out___r__ out___boldp =
       join17 boldp (color land 7) out___r__ out___boldp
     in
     if foreground then
