let setmark_pos ed c pos fnum =
  if c < 0 then
    false
  else if c = Char.code '\'' || c = Char.code '`' then
    (if pos = Win_T.w_cursor_addr ed.st.curwin then
       (setpcmark ed;
        mem_copy ed (Win_T.w_prev_pcmark_addr ed.st.curwin) (Win_T.w_pcmark_addr ed.st.curwin) 16)
     else
       mem_copy ed (Win_T.w_pcmark_addr ed.st.curwin) pos 16;
     true)
  else
    let buf = buflist_findnr ed fnum in
    if buf = 0 then
      false
    else
      match c with
      | 34 (* '\x22' *) ->
          mem_copy ed (Buf_T.b_last_cursor_addr buf) pos 16;
          true
      | 91 (* '[' *) ->
          mem_copy ed (Buf_T.b_op_start_addr buf) pos 16;
          true
      | 93 (* ']' *) ->
          mem_copy ed (Buf_T.b_op_end_addr buf) pos 16;
          true
      | 60 (* '<' *) | 62 (* '>' *) ->
          if c = Char.code '<' then
            mem_copy ed (Buf_T.b_visual_vi_start_addr buf) pos 16
          else
            mem_copy ed (Buf_T.b_visual_vi_end_addr buf) pos 16;
          if Buf_T.b_visual_vi_mode ed buf = nul then
            Buf_T.set_b_visual_vi_mode ed buf (Char.code 'v');
          true
      | _ ->
          if ascii_islower c then
            (mem_copy ed (Buf_T.b_namedm_addr buf + (c - Char.code 'a') * 16) pos 16;
             true)
          else
            false

