       true)
  in
  let join10 c retval =
    Gotchars_state_T.set_pending_mbyte ed state
      (to_u32 ((if c < 0 || c > 255 then 1 else ld_s8 ed (mb_bytelen_tab + c)) - 1));
    join13 c retval
  in
  let t1 = Gotchars_state_T.buflen ed state in
  Gotchars_state_T.set_buflen ed state (Gotchars_state_T.buflen ed state + 1);
  st_u8 ed (Gotchars_state_T.buf_addr state + t1) byte;
  let c = ld_u8 ed (Gotchars_state_T.buf_addr state + t1) in
  let in_special = Gotchars_state_T.pending_special ed state > 0 in
