    (Gotchars_state_T.set_prev_c ed state c;
     false)
  else if in_mbyte then
    (Gotchars_state_T.set_pending_mbyte ed state
       (u32_sub (Gotchars_state_T.pending_mbyte ed state) 1);
     join13 c false)
  else if in_special then
    (if Gotchars_state_T.prev_c ed state = ks_modifier then
