         match Gotchars_state_T.prev_c ed state with
         | 254 (* KS_SPECIAL *) -> 128
         | 255 (* KS_ZERO *) -> -22783
         | _ -> - (Gotchars_state_T.prev_c ed state + i32_shl c 8)
       in
       if c = k_focusgained || c = k_focuslost || c = k_complete_delay then
         Gotchars_state_T.set_buflen ed state 0;
       join10 c false)
  else
