    (let t1 = musl_strlen ed name = 4 && ld_char ed name = 't' && ld_char ed (name + 1) = '_' in
     if t1 then
       (let key = find_key_option ed name false in
        join15 key (key <> 0))
     else
       join15 0 t1)
  else
    let flags = Vimoption.flags ed (options + opt_idx * 112) in
    if flags land p_string = 0 then
      (let (r6, r7, r8, r9) = get_varp_scope ed (options + opt_idx * 112) opt_flags in
       let join7 () =
         if flags land p_num = 0 then
           (let r3 = set_bool_option ed opt_idx varp (to_i32 number) opt_flags in
            frame_pop ed fr;
            r3)
         else
           let r2 = set_num_option ed opt_idx varp number set_option_value__errbuf 80 opt_flags in
           frame_pop ed fr;
           r2
       in
       Optvar_T.set_ov_int ed varp r6;
       Optvar_T.set_ov_long ed varp r7;
       Optvar_T.set_ov_str ed varp r8;
       Optvar_T.set_ov_win ed varp r9;
       if optvar_is_null ed varp then
         join17 ()
       else if number = 0 && string_ <> 0 then
         (let rec loop5 idx =
            if ld_char ed (string_ + idx) = '0' then
              loop5 (idx + 1)
            else if ld_u8 ed (string_ + idx) <> nul || idx = 0 then
              (let r1 = iobuff ed in
               ignore (vim_snprintf ed r1 (emsg_iobuff_room ed)
                  e_number_required_after_str_equal_str [name; string_]);
               ignore (emsg ed (iobuff_or ed e_number_required_after_str_equal_str));
