  else
    let opt_idx = findoption ed tname in
    if opt_idx >= 0 then
      (let (r1, r2, r3, r4) = get_varp ed (options + opt_idx * 112) in
       Optvar_T.set_ov_int ed varp r1;
       Optvar_T.set_ov_long ed varp r2;
       Optvar_T.set_ov_str ed varp r3;
       Optvar_T.set_ov_win ed varp r4;
       if optvar_is_null ed varp then
         (frame_pop ed fr;
          0)
       else
         let r5 = ld_ptr ed (Optvar_T.ov_str ed varp) in
         frame_pop ed fr;
         r5)
    else
      let r6 = find_termcode ed (tname + 2) in
      frame_pop ed fr;
      r6

