and copy_option_val ed val_ =
  if val_ = ed.st.empty_option then ed.st.empty_option else vim_strsave ed val_

and copy_winopt ed from to_ =
  Winopt_T.set_wo_list ed to_ (Winopt_T.wo_list ed from);
  Winopt_T.set_wo_lcs ed to_ (copy_option_val ed (Winopt_T.wo_lcs ed from));
  Winopt_T.set_wo_fcs ed to_ (copy_option_val ed (Winopt_T.wo_fcs ed from));
  Winopt_T.set_wo_nu ed to_ (Winopt_T.wo_nu ed from);
  Winopt_T.set_wo_rnu ed to_ (Winopt_T.wo_rnu ed from);
  Winopt_T.set_wo_ve ed to_ (copy_option_val ed (Winopt_T.wo_ve ed from));
  Winopt_T.set_wo_ve_flags ed to_ (Winopt_T.wo_ve_flags ed from);
  Winopt_T.set_wo_wrap ed to_ (Winopt_T.wo_wrap ed from);
  Winopt_T.set_wo_wcr ed to_ (copy_option_val ed (Winopt_T.wo_wcr ed from));
  Winopt_T.set_wo_sms ed to_ (Winopt_T.wo_sms ed from);
  Winopt_T.set_wo_siso ed to_ (Winopt_T.wo_siso ed from);
  Winopt_T.set_wo_so ed to_ (Winopt_T.wo_so ed from);
  Winopt_T.set_wo_sop ed to_ (Winopt_T.wo_sop ed from);
  Winopt_T.set_wo_wrap_flags ed to_ (Winopt_T.wo_wrap_flags ed from);
  Winopt_T.set_wo_whl ed to_ (copy_option_val ed (Winopt_T.wo_whl ed from));
  check_winopt ed to_

and set_string_option_global ed opt_idx varp =
  let fr = frame_push ed 32 in
  let join3 p s =
    let t1 = not (is_global_option ed opt_idx) && p <> varp in
    let join5 s t1 =
      if t1 then
        (free_string_option (ld_ptr ed p);
         st_ptr ed p s);
      frame_pop ed fr
    in
    if t1 then
      (let s = vim_strsave ed (ld_ptr ed varp) in
       join5 s (s <> 0))
    else
      join5 s t1
  in
  if is_window_local_option ed opt_idx = 0 then
    join3 (get_option_var ed opt_idx) 0
  else
    let (r1, r2, r3, r4) = get_varp_allbuf ed (options + opt_idx * 112) in
    st_ptr ed (fr + 0) r1;
    st_ptr ed (fr + 8) r2;
    st_ptr ed (fr + 16) r3;
    st_s32 ed (fr + 24) r4;
    join3 (Optvar_T.ov_str ed (fr + 0)) 0

and set_string_option_direct ed name opt_idx val_ opt_flags _set_sid =
  let fr = frame_push ed 32 in
  let both = opt_flags land 6 = 0 in
  let join2 idx =
    if is_hidden_option ed idx then
      frame_pop ed fr
    else
      let s = vim_strsave ed val_ in
      let (r1, r2, r3, r4) = get_option_varp_scope ed idx (if both then opt_local else opt_flags) in
      st_ptr ed (fr + 0) r1;
      st_ptr ed (fr + 8) r2;
      st_ptr ed (fr + 16) r3;
      st_s32 ed (fr + 24) r4;
      let varp = Optvar_T.ov_str ed (fr + 0) in
      if opt_flags land opt_free <> 0 && get_option_flags ed idx land p_alloced <> 0 then
        free_string_option (ld_ptr ed varp);
      st_ptr ed varp s;
      if both then set_string_option_global ed idx varp;
      set_option_flag ed idx p_alloced;
      if is_global_local_option ed idx <> 0 && both then
        (free_string_option (ld_ptr ed varp);
         st_ptr ed varp ed.st.empty_option);
      frame_pop ed fr
  in
  if opt_idx = -1 then
    (let idx = findoption ed name in
     if idx < 0 then
       (let r5 = iobuff ed in
        ignore (vim_snprintf ed r5 (emsg_iobuff_room ed) e_internal_error_str
           [165685 (* "set_string_option_direct()" *)]);
        ignore (emsg ed (iobuff_or ed e_internal_error_str));
        let r6 = iobuff ed in
        ignore (vim_snprintf ed r6 (emsg_iobuff_room ed) 165712 (* "For option %s" *) [name]);
        iemsg ed (iobuff_or ed 165712 (* "For option %s" *));
        frame_pop ed fr)
     else
       join2 idx)
  else
    join2 opt_idx

and set_string_option ed opt_idx value opt_flags errbuf errbuflen =
  let fr = frame_push ed 48 in
  let value_checked_addr = fr + 0 in
  st_s32 ed value_checked_addr false_;
  if is_hidden_option ed opt_idx then
    (frame_pop ed fr;
     0)
  else
    let s = vim_strsave ed (if value = 0 then 162263 (* "" *) else value) in
    let (r1, r2, r3, r4) =
      get_option_varp_scope ed opt_idx
        (if opt_flags land 6 = 0 then
           (if is_global_local_option ed opt_idx = 0 then opt_local else opt_global)
         else
           opt_flags)
