and showmatch ed c =
  let fr = frame_push ed 16 in
  let vcol_addr = fr + 0 in
  let so =
    if Win_T.w_onebuf_opt_wo_so ed ed.st.curwin >= 0 then
      Win_T.w_onebuf_opt_wo_so_addr ed.st.curwin
    else
      p_so_addr
  in
  let siso =
    if Win_T.w_onebuf_opt_wo_siso ed ed.st.curwin >= 0 then
      Win_T.w_onebuf_opt_wo_siso_addr ed.st.curwin
    else
      p_siso_addr
  in
  let rec loop1 p =
    let join6 p =
      if ld_u8 ed p = nul then
        frame_pop ed fr
      else
        let lpos = findmatch ed 0 nul in
        if lpos = 0 then
          (vim_beep ed bo_match;
           frame_pop ed fr)
        else if Pos_T.lnum ed lpos < Win_T.w_topline ed ed.st.curwin ||
           Pos_T.lnum ed lpos >= Win_T.w_botline ed ed.st.curwin then
          frame_pop ed fr
        else
          (if Win_T.w_onebuf_opt_wo_wrap ed ed.st.curwin = 0 then
             getvcol ed ed.st.curwin lpos 0 vcol_addr 0 0;
           let col_visible =
             Win_T.w_onebuf_opt_wo_wrap ed ed.st.curwin <> 0 ||
             ld_s32 ed vcol_addr >= Win_T.w_leftcol ed ed.st.curwin &&
             ld_s32 ed vcol_addr < Win_T.w_leftcol ed ed.st.curwin + Win_T.w_width ed ed.st.curwin
           in
           if col_visible then
             (let mpos_lnum = Pos_T.lnum ed lpos in
              let mpos_col = Pos_T.col ed lpos in
              let mpos_coladd = Pos_T.coladd ed lpos in
              let save_cursor_lnum = Win_T.w_cursor_lnum ed ed.st.curwin in
              let save_cursor_col = Win_T.w_cursor_col ed ed.st.curwin in
              let save_cursor_coladd = Win_T.w_cursor_coladd ed ed.st.curwin in
              let save_so = ld_s64 ed so in
              let save_siso = ld_s64 ed siso in
              if ed.st.dollar_vcol >= 0 && ed.st.dollar_vcol = Win_T.w_virtcol ed ed.st.curwin then
                ed.st.dollar_vcol <- -1;
              let r1 = ed.st.curwin in
              Win_T.set_w_virtcol ed r1 (Win_T.w_virtcol ed r1 + 1);
              ignore (update_screen ed upd_valid);
              let save_dollar_vcol = ed.st.dollar_vcol in
              Win_T.set_w_cursor_lnum ed ed.st.curwin mpos_lnum;
              Win_T.set_w_cursor_col ed ed.st.curwin mpos_col;
              Win_T.set_w_cursor_coladd ed ed.st.curwin mpos_coladd;
              st_s64 ed so 0;
              st_s64 ed siso 0;
              showruler ed false;
              setcursor ed;
              cursor_on ed;
              out_flush_cursor ed true false;
              ed.st.dollar_vcol <- save_dollar_vcol;
              if vim_strchr ed (p_cpo ed) cpo_showmatch = 0 then
                (if not (char_avail ed) then ui_delay ed (p_mat ed * 100 + 9) false)
              else
                ui_delay ed (p_mat ed * 100 + 8) true;
              Win_T.set_w_cursor_lnum ed ed.st.curwin save_cursor_lnum;
              Win_T.set_w_cursor_col ed ed.st.curwin save_cursor_col;
              Win_T.set_w_cursor_coladd ed ed.st.curwin save_cursor_coladd;
              st_s64 ed so save_so;
              st_s64 ed siso save_siso;
              frame_pop ed fr)
           else
             frame_pop ed fr)
    in
    if ld_u8 ed p = nul then
      join6 p
    else
      let t1 = utfc_ptr2len ed p + 1 in
      let p = p + t1 in
      if utf_ptr2char ed p = c then
        join6 p
      else
        let t2 = utfc_ptr2len ed p in
        let p = p + t2 in
        if ld_u8 ed p = nul then frame_pop ed fr else loop1 (p + 1)
  in
  loop1 (Buf_T.b_p_mps ed ed.st.curbuf)

