let hexhex2nr ed p =
  if not (vim_isxdigit (ld_u8 ed p)) || not (vim_isxdigit (ld_u8 ed (p + 1))) then
    -1
  else
    let r1 = i32_shl (hex2nr (ld_u8 ed p)) 4 in
    r1 + hex2nr (ld_u8 ed (p + 1))

let rem_backslash ed str =
  ld_char ed str = '\\' && ld_u8 ed (str + 1) <> nul

let freewild count files =
  if not (count <= 0 || files = 0) then
    (let rec loop2 count =
       if count <> 0 then loop2 (count - 1)
     in
     loop2 count)

let free_xp_files_extra ed xp numfiles =
  if Expand_T.xp_files_abbr ed xp <> 0 then
    (freewild numfiles (Expand_T.xp_files_abbr ed xp);
     Expand_T.set_xp_files_abbr ed xp 0);
  if Expand_T.xp_files_kind ed xp <> 0 then
    (freewild numfiles (Expand_T.xp_files_kind ed xp);
     Expand_T.set_xp_files_kind ed xp 0);
  if Expand_T.xp_files_menu ed xp <> 0 then
    (freewild numfiles (Expand_T.xp_files_menu ed xp);
     Expand_T.set_xp_files_menu ed xp 0);
  if Expand_T.xp_files_info ed xp <> 0 then
    (freewild numfiles (Expand_T.xp_files_info ed xp);
     Expand_T.set_xp_files_info ed xp 0)

let expandinit ed xp =
  ignore (musl_memset ed xp 0 80);
  Expand_T.set_xp_backslash ed xp xp_bs_none;
  Expand_T.set_xp_prefix ed xp xp_prefix_none;
  Expand_T.set_xp_numfiles ed xp (-1)

let expandcleanup ed xp =
  if Expand_T.xp_numfiles ed xp >= 0 then
    (free_xp_files_extra ed xp (Expand_T.xp_numfiles ed xp);
     freewild (Expand_T.xp_numfiles ed xp) (Expand_T.xp_files ed xp);
     Expand_T.set_xp_numfiles ed xp (-1));
  Expand_T.set_xp_orig ed xp 0

