let get_histtype ed name =
  let len = to_i32 (musl_strlen ed name) in
  if len = 0 then
    hist_char2type (get_cmdline_firstc ed)
  else
    let rec loop2 i =
      if ld_ptr ed (history_names + i * 8) <> 0 then
        (if musl_strncasecmp ed name (ld_ptr ed (history_names + i * 8)) len = 0 then
           i
