           loop2 (i + 1))
      else if vim_strchr ed 162445 (* ":=@>?/" *) (ld_u8 ed name) <> 0 &&
         ld_u8 ed (name + 1) = nul then
        hist_char2type (ld_u8 ed name)
      else
