    if ld_char ed str = ',' then
      (let str = skipwhite ed (str + 1) in
       let len = vim_str2nr ed str 0 len 0 num_addr 0 0 false 0 in
       if len > 0 then
         (let str = skipwhite ed (str + len) in
          if ld_s64 ed num_addr > int_max then
            (frame_pop ed fr;
             (false, str, num1, num2))
          else
            join11 str (to_i32 (ld_s64 ed num_addr)))
