          (false, str, num1, num2)))
    else if first then join11 str num1 else join11 str num2
  in
  if ld_char ed str = '-' || vim_isdigit (ld_u8 ed str) then
    (let len = vim_str2nr ed str 0 0 0 num_addr 0 0 false 0 in
