let stop_insert ed end_insert_pos esc' nomove =
  let fr = frame_push ed 16 in
  let tpos = fr + 0 in
  let join20 _inserted_string _inserted_length =
    ed.st.did_ai <- false;
    ed.st.did_si <- false;
