    if end_insert_pos <> 0 then
      (mem_copy ed (Buf_T.b_op_start_addr ed.st.curbuf) insstart 16;
       mem_copy ed (Buf_T.b_op_start_orig_addr ed.st.curbuf) insstart_orig 16;
       mem_copy ed (Buf_T.b_op_end_addr ed.st.curbuf) end_insert_pos 16);
    frame_pop ed fr
  in
  let rec loop9 prev_col inserted_string inserted_length =
    let join11 () =
      let cc = gchar_cursor ed in
