          (mem_copy ed (Win_T.w_cursor_addr ed.st.curwin) tpos 16;
           join18 ())
        else if Win_T.w_cursor_col ed ed.st.curwin < prev_col then
          (mem_copy ed tpos (Win_T.w_cursor_addr ed.st.curwin) 16;
