  let added = if r3 = 0 then 0 else to_i32 r4 - ed.st.new_insert_skip in
  if ed.st.did_restart_edit = 0 || added > 0 then
    (String_T.set_string ed last_insert r3;
     String_T.set_length ed last_insert r4;
