        let prev_col = Pos_T.col ed end_insert_pos in
        mem_copy ed (Win_T.w_cursor_addr ed.st.curwin) end_insert_pos 16;
        check_cursor_col ed;
        let strip_col = Win_T.w_cursor_col ed ed.st.curwin in
        let join6 strip_col inserted_string inserted_length =
          if ld_u8 ed (skipwhite ed (ml_get_curline ed + strip_col)) = nul then
            (Win_T.set_w_cursor_col ed ed.st.curwin strip_col;
             loop9 prev_col inserted_string inserted_length)
          else
            (mem_copy ed (Win_T.w_cursor_addr ed.st.curwin) tpos 16;
             join20 inserted_string inserted_length)
        in
        if gchar_cursor ed = nul && strip_col > 0 then
          join6 (strip_col - 1) r3 r4
        else
