let read_redo ed init old_redo =
  let fr = frame_push ed 32 in
  let buf = fr + 0 in
  let join15 c =
    frame_pop ed fr;
    c
  in
  let rec loop6 c n i =
    let join8 c =
      ed.st.read_redo__p <- ed.st.read_redo__p + 1;
      if ld_u8 ed ed.st.read_redo__p = nul && Buffblock_T.b_next ed ed.st.read_redo__bp <> 0 then
        (ed.st.read_redo__bp <- Buffblock_T.b_next ed ed.st.read_redo__bp;
         ed.st.read_redo__p <- Buffblock_T.b_str ed ed.st.read_redo__bp);
      st_u8 ed (buf + i) (to_u8 c);
      if i = n - 1 then
