    (if old_redo then
       ed.st.read_redo__bp <- Buffheader_T.bh_first_b_next ed old_redobuff
     else
       ed.st.read_redo__bp <- Buffheader_T.bh_first_b_next ed redobuff;
     if ed.st.read_redo__bp = 0 then
       (frame_pop ed fr;
