    ed.st.no_mapping <- ed.st.no_mapping - 1;
    ed.st.allow_keys <- ed.st.allow_keys - 1;
    if literally = ctrl_o || literally = ctrl_p then
      (appendchartoredobuff ed ctrl_r;
       appendchartoredobuff ed literally;
       appendchartoredobuff ed regname;
       do_put ed regname 0 (-1) 1
