let cursor_up ed n upd_topline =
  let lnum = Win_T.w_cursor_lnum ed ed.st.curwin in
  if n > 0 && (lnum <= 1 || n >= lnum && vim_strchr ed (p_cpo ed) cpo_minus <> 0) then
    false
  else
    (cursor_up_inner ed ed.st.curwin n;
     ignore (coladvance ed (Win_T.w_curswant ed ed.st.curwin));
