    (if startcol then ignore (coladvance ed (getvcol_nolist ed insstart));
     if old_topline <> Win_T.w_topline ed ed.st.curwin then redraw_later ed upd_valid;
     start_arrow ed tpos;
     join7 ())
  else
    (vim_beep ed bo_crsr;
     join7 ())

