let ins_ctrl_g ed =
  setcursor ed;
  ed.st.no_mapping <- ed.st.no_mapping + 1;
  ed.st.allow_keys <- ed.st.allow_keys + 1;
  let c = plain_vgetc ed in
  ed.st.no_mapping <- ed.st.no_mapping - 1;
  ed.st.allow_keys <- ed.st.allow_keys - 1;
  match c with
  | -30059 (* K_UP *) | 11 (* Ctrl_K *) | 107 (* 'k' *) -> ins_up ed true
  | -25707 (* K_DOWN *) | 10 (* Ctrl_J *) | 106 (* 'j' *) -> ins_down ed true
  | 117 (* 'u' *) ->
      u_sync ed true;
      ed.st.ins_need_undo <- true;
      ed.st.update_Insstart_orig <- false;
      mem_copy ed insstart (Win_T.w_cursor_addr ed.st.curwin) 16
  | 85 (* 'U' *) -> ed.st.dont_sync_undo <- maybe
  | 27 (* ESC *) -> ()
  | _ -> vim_beep ed bo_ctrlg

