  Typebuf_T.tb_maplen ed typebuf = 0

let may_start_select ed c =
  ed.st.visual_select <-
    Bool.to_int
      ((c = Char.code 'o' || stuff_empty ed && typebuf_typed ed) && vim_strchr ed (p_slm ed) c <> 0)

