  else
    let r1 = iobuff ed in
    let r2 = emsg_iobuff_room ed in
    ignore (vim_snprintf ed r1 r2 e_invalid_argument_str [ld_ptr ed arg_addr]);
    ignore (emsg ed (iobuff_or ed e_invalid_argument_str));
    frame_pop ed fr

let get_sw_value_pos ed buf pos left =
