let block_prep ed oap bdp lnum is_del =
  let cts = Chartabsize_T.make () in
  let rec loop1 incr line prev_pstart =
    if cts.cts_vcol < Oparg_T.start_vcol ed oap && ld_u8 ed cts.cts_ptr <> nul then
      (let incr = lbr_chartabsize ed cts in
       cts.cts_vcol <- cts.cts_vcol + incr;
       if ld_char ed cts.cts_ptr = ' ' || ld_char ed cts.cts_ptr = '\t' then
         (Block_def.set_pre_whitesp ed bdp (Block_def.pre_whitesp ed bdp + incr);
          Block_def.set_pre_whitesp_c ed bdp (Block_def.pre_whitesp_c ed bdp + 1))
       else
         (Block_def.set_pre_whitesp ed bdp 0;
          Block_def.set_pre_whitesp_c ed bdp 0);
       let prev_pstart = cts.cts_ptr in
       let t1 = utfc_ptr2len ed cts.cts_ptr in
       cts.cts_ptr <- cts.cts_ptr + t1;
       loop1 incr line prev_pstart)
    else
      (Block_def.set_start_vcol ed bdp cts.cts_vcol;
       let pstart = cts.cts_ptr in
       let join28 pstart =
         Block_def.set_textcol ed bdp (to_i32 (pstart - line));
         Block_def.set_textstart ed bdp pstart
       in
       let join23 incr pend =
         let join25 pstart =
           Block_def.set_textlen ed bdp (to_i32 (pend - pstart));
           join28 pstart
         in
         Block_def.set_end_char_vcols ed bdp incr;
         if is_del <> 0 && Block_def.startspaces ed bdp <> 0 then
           join25 prev_pstart
         else
           join25 pstart
       in
       Block_def.set_start_char_vcols ed bdp incr;
       if Block_def.start_vcol ed bdp < Oparg_T.start_vcol ed oap then
         (Block_def.set_end_vcol ed bdp (Block_def.start_vcol ed bdp);
          Block_def.set_is_short ed bdp true;
          if is_del = 0 || Oparg_T.op_type ed oap = op_append then
            Block_def.set_endspaces ed
              bdp (Oparg_T.end_vcol ed oap - Oparg_T.start_vcol ed oap + 1);
          join28 pstart)
       else
         (Block_def.set_startspaces ed
            bdp (Block_def.start_vcol ed bdp - Oparg_T.start_vcol ed oap);
          if is_del <> 0 && Block_def.startspaces ed bdp <> 0 then
            Block_def.set_startspaces ed bdp
              (Block_def.start_char_vcols ed bdp - Block_def.startspaces ed bdp);
          Block_def.set_end_vcol ed bdp (Block_def.start_vcol ed bdp);
          if Block_def.end_vcol ed bdp > Oparg_T.end_vcol ed oap then
            (Block_def.set_is_oneChar ed bdp true;
             (match Oparg_T.op_type ed oap with
              | 17 (* OP_INSERT *) ->
                  Block_def.set_endspaces ed bdp
                    (Block_def.start_char_vcols ed bdp - Block_def.startspaces ed bdp)
              | 18 (* OP_APPEND *) ->
                  Block_def.set_startspaces ed bdp
                    (Block_def.startspaces ed bdp +
                     (Oparg_T.end_vcol ed oap - Oparg_T.start_vcol ed oap + 1));
                  Block_def.set_endspaces ed bdp
                    (Block_def.start_char_vcols ed bdp - Block_def.startspaces ed bdp)
              | _ ->
                  Block_def.set_startspaces ed bdp
                    (Oparg_T.end_vcol ed oap - Oparg_T.start_vcol ed oap + 1);
                  if is_del <> 0 && Oparg_T.op_type ed oap <> op_lshift then
                    (Block_def.set_startspaces ed bdp
                       (Block_def.start_char_vcols ed bdp -
                        (Block_def.start_vcol ed bdp - Oparg_T.start_vcol ed oap));
                     Block_def.set_endspaces ed bdp
                       (Block_def.end_vcol ed bdp - Oparg_T.end_vcol ed oap - 1)));
             join23 incr pstart)
          else
            (init_chartabsize_arg ed cts ed.st.curwin lnum (Block_def.end_vcol ed bdp) line pstart;
             let rec loop7 incr prev_pend =
               if cts.cts_vcol <= Oparg_T.end_vcol ed oap && ld_u8 ed cts.cts_ptr <> nul then
                 (let prev_pend = cts.cts_ptr in
                  let incr = lbr_chartabsize_adv ed cts in
                  cts.cts_vcol <- cts.cts_vcol + incr;
                  loop7 incr prev_pend)
               else
                 (Block_def.set_end_vcol ed bdp cts.cts_vcol;
                  let pend = cts.cts_ptr in
                  if Block_def.end_vcol ed bdp <= Oparg_T.end_vcol ed oap &&
                     (is_del = 0 ||
                      Oparg_T.op_type ed oap = op_append ||
                      Oparg_T.op_type ed oap = op_replace') then
                    (Block_def.set_is_short ed bdp true;
                     if Oparg_T.op_type ed oap = op_append || ed.st.virtual_op <> 0 then
                       Block_def.set_endspaces ed bdp
                         (Oparg_T.end_vcol ed oap - Block_def.end_vcol ed bdp +
                          Oparg_T.inclusive ed oap)
                     else
                       Block_def.set_endspaces ed bdp 0;
                     join23 incr pend)
                  else if Block_def.end_vcol ed bdp > Oparg_T.end_vcol ed oap then
                    (Block_def.set_endspaces ed bdp
                       (Block_def.end_vcol ed bdp - Oparg_T.end_vcol ed oap - 1);
                     if is_del = 0 && Block_def.endspaces ed bdp <> 0 then
                       (Block_def.set_endspaces ed bdp (incr - Block_def.endspaces ed bdp);
                        if pend = pstart then join23 incr pend else join23 incr prev_pend)
                     else
                       join23 incr pend)
                  else
                    join23 incr pend)
             in
             loop7 incr pstart)))
  in
  Block_def.set_startspaces ed bdp 0;
  Block_def.set_endspaces ed bdp 0;
  Block_def.set_textlen ed bdp 0;
  Block_def.set_start_vcol ed bdp 0;
  Block_def.set_end_vcol ed bdp 0;
  Block_def.set_is_short ed bdp false;
  Block_def.set_is_oneChar ed bdp false;
  Block_def.set_pre_whitesp ed bdp 0;
  Block_def.set_pre_whitesp_c ed bdp 0;
  Block_def.set_end_char_vcols ed bdp 0;
  Block_def.set_start_char_vcols ed bdp 0;
  let line = ml_get ed lnum in
  init_chartabsize_arg ed cts ed.st.curwin lnum (Block_def.start_vcol ed bdp) line line;
  loop1 0 line line

let shift_block ed oap amount =
  let fr = frame_push ed 64 in
  let bd = fr + 0 in
  let cts = Chartabsize_T.make () in
  let cts_2 = Chartabsize_T.make () in
  let left = Oparg_T.op_type ed oap = op_lshift in
  let oldstate = ed.st.state in
  let oldcol = Win_T.w_cursor_col ed ed.st.curwin in
  let sw_val = to_i32 (get_sw_value_indent ed ed.st.curbuf left) in
  let ts_val = to_i32 (Buf_T.b_p_ts ed ed.st.curbuf) in
  ed.st.state <- mode_insert;
  block_prep ed oap bd (Win_T.w_cursor_lnum ed ed.st.curwin) true_;
  if Block_def.is_short ed bd then
    frame_pop ed fr
  else
    let total = to_i32 (u32_mul (to_u32 amount) (to_u32 sw_val)) in
    if total / sw_val = amount then
      (let oldp = ml_get_curline ed in
       let oldlen = ml_get_curline_len ed in
       let join27 newp new_line_len =
         let join30 added =
           inserted_bytes ed (Win_T.w_cursor_lnum ed ed.st.curwin) (Block_def.textcol ed bd) added;
           ed.st.state <- oldstate;
           Win_T.set_w_cursor_col ed ed.st.curwin oldcol;
           frame_pop ed fr
         in
         ignore (ml_replace ed (Win_T.w_cursor_lnum ed ed.st.curwin) newp false);
         if u64_ge new_line_len oldlen then
           join30 (to_i32 (new_line_len - oldlen))
         else
           join30 (- to_i32 (oldlen - new_line_len))
       in
       if left then
         (let non_white = Block_def.textstart ed bd in
          let join5 non_white =
            let non_white_col = Block_def.start_vcol ed bd in
            init_chartabsize_arg ed cts_2 ed.st.curwin (Win_T.w_cursor_lnum ed ed.st.curwin)
              non_white_col (Block_def.textstart ed bd) non_white;
            let rec loop6 () =
              if ld_char ed cts_2.cts_ptr = ' ' || ld_char ed cts_2.cts_ptr = '\t' then
                (let incr = lbr_chartabsize_adv ed cts_2 in
                 cts_2.cts_vcol <- cts_2.cts_vcol + incr;
                 loop6 ())
              else
                let non_white_col = cts_2.cts_vcol in
                let non_white = cts_2.cts_ptr in
                let block_space_width = non_white_col - Oparg_T.start_vcol ed oap in
                let shift_amount =
                  if u64_lt block_space_width total then block_space_width else total
                in
                let destination_col = to_i32 (non_white_col - shift_amount) in
                let verbatim_copy_end = Block_def.textstart ed bd in
                let verbatim_copy_width = Block_def.start_vcol ed bd in
                let join9 verbatim_copy_width =
                  init_chartabsize_arg ed cts_2 ed.st.curwin 0 verbatim_copy_width
                    (Block_def.textstart ed bd) verbatim_copy_end;
                  let rec loop10 () =
                    let join13 () =
                      let verbatim_copy_width = cts_2.cts_vcol in
                      let verbatim_copy_end = cts_2.cts_ptr in
                      let fill = destination_col - verbatim_copy_width in
                      let fixedlen = verbatim_copy_end - oldp in
                      let new_line_len = fixedlen + fill + (oldlen - (non_white - oldp)) in
                      let newp = alloc ed (new_line_len + 1) in
                      ignore (musl_memmove ed newp oldp fixedlen);
                      ignore (musl_memset ed (newp + fixedlen) (Char.code ' ') fill);
                      ignore (musl_strcpy ed (newp + fixedlen + fill) non_white);
                      join27 newp new_line_len
                    in
                    if cts_2.cts_vcol < destination_col then
                      (let incr = lbr_chartabsize ed cts_2 in
                       if cts_2.cts_vcol + incr > destination_col then
                         join13 ()
                       else
                         (cts_2.cts_vcol <- cts_2.cts_vcol + incr;
                          let t2 = utfc_ptr2len ed cts_2.cts_ptr in
                          cts_2.cts_ptr <- cts_2.cts_ptr + t2;
                          loop10 ()))
                    else
                      join13 ()
                  in
                  loop10 ()
                in
                if Block_def.startspaces ed bd = 0 then
                  join9 verbatim_copy_width
                else
                  join9 (verbatim_copy_width - Block_def.start_char_vcols ed bd)
            in
            loop6 ()
          in
          if Block_def.startspaces ed bd = 0 then
            join5 non_white
          else
            join5 (non_white + utfc_ptr2len ed non_white))
       else
         let total = total + Block_def.pre_whitesp ed bd in
         let ws_vcol = Block_def.start_vcol ed bd - Block_def.pre_whitesp ed bd in
         let join19 ws_vcol tabs =
           init_chartabsize_arg ed cts ed.st.curwin (Win_T.w_cursor_lnum ed ed.st.curwin)
             (Block_def.start_vcol ed bd) (Block_def.textstart ed bd) (Block_def.textstart ed bd);
           let rec loop20 total =
             let join23 tabs =
               let join26 spaces =
                 Block_def.set_textcol ed bd
                   (Block_def.textcol ed bd -
                    (Block_def.pre_whitesp_c ed bd -
                     Bool.to_int (Block_def.startspaces ed bd <> 0)));
                 let new_line_len =
                   Block_def.textcol ed bd + tabs + spaces +
                   (oldlen - (Block_def.textstart ed bd - oldp))
                 in
                 let newp = alloc ed (new_line_len + 1) in
                 ignore (musl_memmove ed newp oldp (Block_def.textcol ed bd));
                 let newlen = Block_def.textcol ed bd in
                 ignore (musl_memset ed (newp + newlen) tab tabs);
                 let newlen = newlen + tabs in
                 ignore (musl_memset ed (newp + newlen) (Char.code ' ') spaces);
                 ignore (musl_strcpy ed (newp + newlen + spaces) (Block_def.textstart ed bd));
                 join27 newp new_line_len
               in
               if tabs > 0 then join26 ((ws_vcol mod ts_val + total) mod ts_val) else join26 total
             in
             if ld_char ed cts.cts_ptr = ' ' || ld_char ed cts.cts_ptr = '\t' then
               (let incr = lbr_chartabsize_adv ed cts in
                cts.cts_vcol <- cts.cts_vcol + incr;
                loop20 (total + incr))
             else
               (Block_def.set_textstart ed bd cts.cts_ptr;
                Block_def.set_start_vcol ed bd cts.cts_vcol;
                if Buf_T.b_p_et ed ed.st.curbuf = 0 then
                  join23 ((ws_vcol mod ts_val + total) / ts_val)
                else
                  join23 tabs)
           in
           loop20 total
         in
         if Block_def.startspaces ed bd = 0 then
           join19 ws_vcol 0
         else if utfc_ptr2len ed (Block_def.textstart ed bd) = 1 then
           (Block_def.set_textstart ed bd (Block_def.textstart ed bd + 1);
            join19 ws_vcol 0)
         else
           (Block_def.set_startspaces ed bd 0;
            join19 0 0))
    else
      frame_pop ed fr

let op_shift ed oap curs_top amount =
  let join15 () =
    if Cmdmod_T.cmod_flags ed cmdmod land cmod_lockmarks = 0 then
      (mem_copy ed (Buf_T.b_op_start_addr ed.st.curbuf) (Oparg_T.start_addr oap) 16;
       Buf_T.set_b_op_end_lnum ed ed.st.curbuf (Oparg_T.end_lnum ed oap);
       let r4 = ed.st.curbuf in
       Buf_T.set_b_op_end_col ed r4 (ml_get_len ed (Oparg_T.end_lnum ed oap));
       if Buf_T.b_op_end_col ed ed.st.curbuf > 0 then
         (let r5 = ed.st.curbuf in
          Buf_T.set_b_op_end_col ed r5 (Buf_T.b_op_end_col ed r5 - 1)))
  in
  let join14 op =
    let msg_line_single =
      ngettext 164899 (* "%ld line %sed %d time" *) 164921 (* "%ld line %sed %d times" *) amount
    in
    let msg_line_plural =
      ngettext 164944 (* "%ld lines %sed %d time" *) 164967 (* "%ld lines %sed %d times" *) amount
    in
    let r2 = iobuff ed in
    let r3 = ngettext msg_line_single msg_line_plural (Oparg_T.line_count ed oap) in
    ignore (vim_snprintf ed r2 1025 r3 [Oparg_T.line_count ed oap; op; amount]);
    ignore (msg_attr_keep ed (iobuff ed) 0 true);
    join15 ()
  in
  let join10 () =
    if Oparg_T.line_count ed oap > p_report ed then
      (if Oparg_T.op_type ed oap = op_rshift then
         join14 164897 (* ">" *)
       else
         join14 162541 (* "<" *))
    else
      join15 ()
  in
  let rec loop4 i block_col =
    let i = i - 1 in
    if i >= 0 then
      (let first_char = ld_u8 ed (ml_get_curline ed) in
       if first_char = nul then
         Win_T.set_w_cursor_col ed ed.st.curwin 0
       else if Oparg_T.block_mode ed oap = 0 then
         (if first_char <> Char.code '#' || preprocs_left ed = 0 then
            shift_line ed (Oparg_T.op_type ed oap = op_lshift) (p_sr ed) amount false)
       else
         shift_block ed oap amount;
       let r6 = ed.st.curwin in
       Win_T.set_w_cursor_lnum ed r6 (Win_T.w_cursor_lnum ed r6 + 1);
       loop4 i block_col)
    else
      (changed_lines ed (Oparg_T.start_lnum ed oap) 0 (Oparg_T.end_lnum ed oap + 1) 0;
       if Oparg_T.block_mode ed oap <> 0 then
         (Win_T.set_w_cursor_lnum ed ed.st.curwin (Oparg_T.start_lnum ed oap);
          Win_T.set_w_cursor_col ed ed.st.curwin block_col;
          join10 ())
       else if curs_top then
         (Win_T.set_w_cursor_lnum ed ed.st.curwin (Oparg_T.start_lnum ed oap);
          beginline ed 6;
          join10 ())
       else
         let r1 = ed.st.curwin in
         Win_T.set_w_cursor_lnum ed r1 (Win_T.w_cursor_lnum ed r1 - 1);
         join10 ())
  in
  let join3 block_col =
    loop4 (Oparg_T.line_count ed oap) block_col
  in
  if u_save ed (Oparg_T.start_lnum ed oap - 1) (Oparg_T.end_lnum ed oap + 1) then
    (if Oparg_T.block_mode ed oap = 0 then join3 0 else join3 (Win_T.w_cursor_col ed ed.st.curwin))

let getviscol2 ed col coladd =
  let fr = frame_push ed 32 in
  let x_addr = fr + 0 in
  let pos = fr + 8 in
  Pos_T.set_lnum ed pos (Win_T.w_cursor_lnum ed ed.st.curwin);
  Pos_T.set_col ed pos col;
  Pos_T.set_coladd ed pos coladd;
  getvvcol ed ed.st.curwin pos x_addr 0 0 0;
  let r1 = ld_s32 ed x_addr in
  frame_pop ed fr;
  r1

let mb_adjust_opend ed oap =
  if Oparg_T.inclusive ed oap <> 0 then
    (let line = ml_get ed (Oparg_T.end_lnum ed oap) in
     let ptr = line + Oparg_T.end_col ed oap in
     if ld_u8 ed ptr <> nul then
       (let t1 = utf_head_off ed line ptr in
        let ptr = ptr + -t1 in
        let t2 = utfc_ptr2len ed ptr - 1 in
        Oparg_T.set_end_col ed oap (to_i32 (ptr + t2 - line))))

let reset_y_append ed =
  ed.st.y_append <- false

let free_yank ed n =
  if Yankreg_T.y_array ed ed.st.y_current <> 0 then
    (let rec loop2 i =
       let i = i - 1 in
       if i >= 0 then
         (String_T.set_string ed (Yankreg_T.y_array ed ed.st.y_current + i * 16) 0;
          String_T.set_length ed (Yankreg_T.y_array ed ed.st.y_current + i * 16) 0;
          loop2 i)
       else
         Yankreg_T.set_y_array ed ed.st.y_current 0
     in
     loop2 n)

let free_yank_all ed =
  free_yank ed (Yankreg_T.y_size ed ed.st.y_current)

let shift_delete_registers ed =
  ed.st.y_current <- y_regs + 216;
  free_yank_all ed;
  let rec loop1 n =
    if n > 1 then
      (mem_copy ed (y_regs + n * 24) (y_regs + (n - 1) * 24) 24;
       loop1 (n - 1))
    else
      (ed.st.y_current <- y_regs + 24;
       if not ed.st.y_append then ed.st.y_previous <- ed.st.y_current;
       Yankreg_T.set_y_array ed (y_regs + 24) 0)
  in
  loop1 9

let update_topline_redraw ed =
  update_topline ed;
  if ed.st.must_redraw <> 0 then ignore (update_screen ed 0)

let charwise_block_prep ed start_in end_in bdp lnum inclusive =
  let fr = frame_push ed 48 in
  let start = fr + 0 in
  let end_' = fr + 16 in
  let cs_addr = fr + 32 in
  let ce_addr = fr + 36 in
  mem_copy ed start start_in 16;
  mem_copy ed end_' end_in 16;
  let plen = ml_get_len ed lnum in
  let p = ml_get ed lnum in
  let join6 startcol endcol =
    let join12 endcol =
      let join14 endcol =
        if startcol > endcol || Block_def.is_oneChar ed bdp then
          Block_def.set_textlen ed bdp 0
        else
          Block_def.set_textlen ed bdp (endcol - startcol + inclusive);
        Block_def.set_textcol ed bdp startcol;
        Block_def.set_textstart ed bdp (if startcol <= plen then p + startcol else p);
        frame_pop ed fr
      in
      if endcol = maxcol then join14 (ml_get_len ed lnum) else join14 endcol
    in
    if lnum = Pos_T.lnum ed end_' then
      (let endcol = Pos_T.col ed end_' in
       if ed.st.virtual_op = 0 then
         join12 endcol
       else
         (getvcol ed ed.st.curwin end_' cs_addr 0 ce_addr 0;
          if ld_u8 ed (p + endcol) = nul ||
             ld_s32 ed cs_addr + Pos_T.coladd ed end_' < ld_s32 ed ce_addr &&
             utf_head_off ed p (p + endcol) = 0 then
            (if Pos_T.lnum ed start = Pos_T.lnum ed end_' &&
                Pos_T.col ed start = Pos_T.col ed end_' then
               (Block_def.set_is_oneChar ed bdp true;
                Block_def.set_startspaces ed bdp
                  (Pos_T.coladd ed end_' - Pos_T.coladd ed start + inclusive);
                join12 startcol)
             else
               (Block_def.set_endspaces ed bdp (Pos_T.coladd ed end_' + inclusive);
                join12 (endcol - inclusive)))
          else
            join12 endcol))
    else
      join12 endcol
  in
  Block_def.set_startspaces ed bdp 0;
  Block_def.set_endspaces ed bdp 0;
  Block_def.set_is_oneChar ed bdp false;
  Block_def.set_start_char_vcols ed bdp 0;
  if lnum = Pos_T.lnum ed start then
    (let startcol = Pos_T.col ed start in
     if ed.st.virtual_op = 0 then
