         else
           join33 target closest uhp mark nomark dofile above did_undo
       in
       let join31 target =
         join33 target (-1) uhp mark nomark dofile above did_undo
       in
       if step < 0 then
         (if target < 0 then join31 0 else join31 target)
       else if dosec then
         join27 (host_time ed + 1)
       else if dofile then
         join27 (Buf_T.b_u_save_nr_last ed ed.st.curbuf + 2)
       else
         join27 (Buf_T.b_u_seq_last ed ed.st.curbuf + 2)
     in
     ed.st.u_newcount <- 0;
     ed.st.u_oldcount <- 0;
     if Buf_T.b_ml_ml_flags ed ed.st.curbuf land ml_empty <> 0 then ed.st.u_oldcount <- -1;
     if absolute then
       join33 step (-1) 0 0 0 dofile false true
     else if dosec then
       join21 (Buf_T.b_u_time_cur ed ed.st.curbuf + step) 0 0 0 dofile false true
     else if dofile then
       (if step < 0 then
          (let uhp = Buf_T.b_u_curhead ed ed.st.curbuf in
           let join15 uhp mark nomark above did_undo =
             let join18 target =
               if target <= 0 then
                 join21 target uhp mark nomark false above did_undo
