          if target > Buf_T.b_u_save_nr_last ed ed.st.curbuf then
            join21 (Buf_T.b_u_seq_last ed ed.st.curbuf + 1) 0 0 0 false false true
          else
            join21 target 0 0 0 dofile false true)
     else
       join21 (Buf_T.b_u_seq_cur ed ed.st.curbuf + step) 0 0 0 dofile false true)

