let ex_later ed eap =
  let fr = frame_push ed 16 in
  let p_addr = fr + 0 in
  let join12 () =
    frame_pop ed fr
  in
  let join9 count sec file =
    if ld_u8 ed (ld_ptr ed p_addr) = nul then
