let stuffReadbuff ed s =
  add_buff ed readbuf1 s (-1)

let stuffnumReadbuff ed n =
  add_num_buff ed readbuf1 n

let op_colon ed oap =
  stuffcharReadbuff ed (Char.code ':');
  if Oparg_T.is_VIsual ed oap = 0 then
    (if Oparg_T.start_lnum ed oap = Win_T.w_cursor_lnum ed ed.st.curwin then
       stuffcharReadbuff ed (Char.code '.')
     else
       stuffnumReadbuff ed (Oparg_T.start_lnum ed oap);
     if Oparg_T.end_lnum ed oap <> Oparg_T.start_lnum ed oap then
       (stuffcharReadbuff ed (Char.code ',');
        if Oparg_T.end_lnum ed oap = Win_T.w_cursor_lnum ed ed.st.curwin then
          stuffcharReadbuff ed (Char.code '.')
        else if Oparg_T.end_lnum ed oap = Buf_T.b_ml_ml_line_count ed ed.st.curbuf then
          stuffcharReadbuff ed (Char.code '$')
        else if Oparg_T.start_lnum ed oap = Win_T.w_cursor_lnum ed ed.st.curwin then
          (stuffReadbuff ed 165428 (* ".+" *);
           stuffnumReadbuff ed (Oparg_T.line_count ed oap - 1))
        else
          stuffnumReadbuff ed (Oparg_T.end_lnum ed oap)))
  else
    stuffReadbuff ed 163231 (* "'<,'>" *)

