    mem_copy ed (Win_T.w_cursor_addr ed.st.curwin) (Oparg_T.start_addr oap) 16;
    ignore (coladvance ed (Oparg_T.start_vcol ed oap));
    mem_copy ed (Oparg_T.start_addr oap) (Win_T.w_cursor_addr ed.st.curwin) 16;
    frame_pop ed fr
