let is_zero_width ed pattern patternlen move cur direction =
  let fr = frame_push ed 368 in
  let regmatch = fr + 0 in
  let pos = fr + 344 in
  let join12 result =
    vim_regfree (Regmmatch_T.regprog ed regmatch);
    frame_pop ed fr;
    result
  in
  let called_emsg_before = ed.st.called_emsg in
  let join2 pattern patternlen result flag =
    let join6 flag =
      if searchit ed ed.st.curwin ed.st.curbuf pos 0 direction pattern patternlen 1
           (search_keep + flag) re_search 0 =
         fail then
        join12 result
      else
        let rec loop8 () =
          Lpos_T.set_col ed (Regmmatch_T.startpos_addr regmatch)
            (Lpos_T.col ed (Regmmatch_T.startpos_addr regmatch) + 1);
          let nmatched =
            to_i32
              (vim_regexec_multi ed regmatch ed.st.curwin ed.st.curbuf (Pos_T.lnum ed pos)
                 (Lpos_T.col ed (Regmmatch_T.startpos_addr regmatch)) 0)
          in
          let join10 () =
            if ed.st.called_emsg = called_emsg_before then
              join12
                (Bool.to_int
                   (nmatched <> 0 &&
                    Lpos_T.lnum ed (Regmmatch_T.startpos_addr regmatch) =
                    Lpos_T.lnum ed (Regmmatch_T.endpos_addr regmatch) &&
                    Lpos_T.col ed (Regmmatch_T.startpos_addr regmatch) =
                    Lpos_T.col ed (Regmmatch_T.endpos_addr regmatch)))
            else
              join12 result
          in
          if nmatched <> 0 then
            join10 ()
          else if Regmmatch_T.regprog ed regmatch <> 0 &&
             (if direction = forward then
                Bool.to_int (Lpos_T.col ed (Regmmatch_T.startpos_addr regmatch) < Pos_T.col ed pos)
              else
                Bool.to_int
                  (Lpos_T.col ed (Regmmatch_T.startpos_addr regmatch) > Pos_T.col ed pos)) <>
             0 then
            loop8 ()
          else
            join10 ()
        in
        loop8 ()
    in
    if search_regcomp ed pattern patternlen 0 re_search re_search search_keep regmatch then
      (Lpos_T.set_col ed (Regmmatch_T.startpos_addr regmatch) (-1);
       if move then
         (Pos_T.set_lnum ed pos 0;
          Pos_T.set_col ed pos 0;
          Pos_T.set_coladd ed pos 0;
          join6 flag)
       else
         (mem_copy ed pos cur 16;
          join6 search_start))
    else
      (frame_pop ed fr;
       -1)
  in
  if pattern = 0 then
    (let pattern = Spat_T.pat ed (spats + ed.st.last_idx * 48) in
     join2 pattern (Spat_T.patlen ed (spats + ed.st.last_idx * 48)) (-1) 0)
