let current_search ed count forward' =
  let fr = frame_push ed 32 in
  let end_pos = fr + 0 in
  let pos = fr + 16 in
  let rec loop8 i old_p_ws zero_width skip_first_backward orig_pos_lnum orig_pos_col orig_pos_coladd save_VIsual_lnum save_VIsual_col save_VIsual_coladd =
    let join39 () =
      loop8 (i + 1) old_p_ws zero_width skip_first_backward orig_pos_lnum orig_pos_col
        orig_pos_coladd save_VIsual_lnum save_VIsual_col save_VIsual_coladd
    in
    let join27 dir =
      let join29 flags =
        mem_copy ed end_pos pos 16;
        if i = 0 then set_p_ws ed false_;
        let result =
          searchit ed ed.st.curwin ed.st.curbuf pos end_pos (if dir = 0 then -1 else forward)
            (Spat_T.pat ed (spats + ed.st.last_idx * 48))
            (Spat_T.patlen ed (spats + ed.st.last_idx * 48)) (if i = 0 then 1 else count)
            (search_keep lor flags) re_search 0
        in
        set_p_ws ed old_p_ws;
        if i = 1 && result = 0 then
          (let r1 = ed.st.curwin in
           Win_T.set_w_cursor_lnum ed r1 orig_pos_lnum;
           Win_T.set_w_cursor_col ed r1 orig_pos_col;
           Win_T.set_w_cursor_coladd ed r1 orig_pos_coladd;
           if ed.st.visual_active then
             (Pos_T.set_lnum ed visual save_VIsual_lnum;
              Pos_T.set_col ed visual save_VIsual_col;
              Pos_T.set_coladd ed visual save_VIsual_coladd);
           frame_pop ed fr;
           false)
        else
          (if i = 0 && result = 0 then
             (if forward' then
                (Pos_T.set_lnum ed pos 0;
                 Pos_T.set_col ed pos 0;
                 Pos_T.set_coladd ed pos 0)
              else
                (Pos_T.set_lnum ed pos
                   (Buf_T.b_ml_ml_line_count ed (Win_T.w_buffer ed ed.st.curwin));
                 Pos_T.set_col ed pos
                   (ml_get_len ed (Buf_T.b_ml_ml_line_count ed (Win_T.w_buffer ed ed.st.curwin)))));
           join39 ())
      in
      if dir = 0 && zero_width = 0 then join29 search_end else join29 0
    in
    if i < 2 then
      (if forward' then
         (if i = 0 && skip_first_backward then join39 () else join27 i)
       else
         join27 (Bool.to_int (i = 0)))
    else
      let start_pos_lnum = Pos_T.lnum ed pos in
      let start_pos_col = Pos_T.col ed pos in
      let start_pos_coladd = Pos_T.coladd ed pos in
      if not ed.st.visual_active then
        (Pos_T.set_lnum ed visual start_pos_lnum;
