               Bool.to_int (Pos_T.coladd ed visual < Pos_T.coladd ed end_pos)
             else
               Bool.to_int (Pos_T.col ed visual < Pos_T.col ed end_pos))
          else
            Bool.to_int (Pos_T.lnum ed visual < Pos_T.lnum ed end_pos)) <>
         0 &&
         forward' then
        (if skip_first_backward then
           mem_copy ed (Win_T.w_cursor_addr ed.st.curwin) pos 16
         else
           ignore (dec_cursor ed))
      else
        if ed.st.visual_active &&
           (if Win_T.w_cursor_lnum ed ed.st.curwin = Pos_T.lnum ed visual then
              (if Win_T.w_cursor_col ed ed.st.curwin = Pos_T.col ed visual then
                 Bool.to_int (Win_T.w_cursor_coladd ed ed.st.curwin < Pos_T.coladd ed visual)
               else
                 Bool.to_int (Win_T.w_cursor_col ed ed.st.curwin < Pos_T.col ed visual))
            else
              Bool.to_int (Win_T.w_cursor_lnum ed ed.st.curwin < Pos_T.lnum ed visual)) <>
           0 &&
           forward' then
          mem_copy ed (Win_T.w_cursor_addr ed.st.curwin) pos 16;
      ed.st.visual_active <- true;
      ed.st.visual_mode <- Char.code 'v';
      if ld_char ed (p_sel ed) = 'e' then
        (if forward' &&
            ((if Pos_T.lnum ed visual = Win_T.w_cursor_lnum ed ed.st.curwin then
                (if Pos_T.col ed visual = Win_T.w_cursor_col ed ed.st.curwin then
                   Bool.to_int (Pos_T.coladd ed visual < Win_T.w_cursor_coladd ed ed.st.curwin)
                 else
                   Bool.to_int (Pos_T.col ed visual < Win_T.w_cursor_col ed ed.st.curwin))
              else
                Bool.to_int (Pos_T.lnum ed visual < Win_T.w_cursor_lnum ed ed.st.curwin)) <>
             0 ||
             Pos_T.lnum ed visual = Win_T.w_cursor_lnum ed ed.st.curwin &&
             Pos_T.col ed visual = Win_T.w_cursor_col ed ed.st.curwin &&
             Pos_T.coladd ed visual = Win_T.w_cursor_coladd ed ed.st.curwin) then
           ignore (inc_cursor ed)
         else
           if not forward' &&
              ((if Win_T.w_cursor_lnum ed ed.st.curwin = Pos_T.lnum ed visual then
                  (if Win_T.w_cursor_col ed ed.st.curwin = Pos_T.col ed visual then
                     Bool.to_int (Win_T.w_cursor_coladd ed ed.st.curwin < Pos_T.coladd ed visual)
                   else
                     Bool.to_int (Win_T.w_cursor_col ed ed.st.curwin < Pos_T.col ed visual))
                else
                  Bool.to_int (Win_T.w_cursor_lnum ed ed.st.curwin < Pos_T.lnum ed visual)) <>
               0 ||
               Win_T.w_cursor_lnum ed ed.st.curwin = Pos_T.lnum ed visual &&
               Win_T.w_cursor_col ed ed.st.curwin = Pos_T.col ed visual &&
               Win_T.w_cursor_coladd ed ed.st.curwin = Pos_T.coladd ed visual) then
             ignore (inc ed visual));
      may_start_select ed (Char.code 'c');
      redraw_curbuf_later ed upd_inverted;
      ignore (showmode ed);
      frame_pop ed fr;
      true
  in
  let old_p_ws = to_u8 (p_ws ed) in
  let save_VIsual_lnum = Pos_T.lnum ed visual in
  let save_VIsual_col = Pos_T.col ed visual in
  let save_VIsual_coladd = Pos_T.coladd ed visual in
  if ed.st.visual_active &&
