  let orig_pos_col = Pos_T.col ed pos in
  let orig_pos_coladd = Pos_T.coladd ed pos in
  if ed.st.visual_active then (if forward' then ignore (incl ed pos) else ignore (decl ed pos));
  let zero_width =
    is_zero_width ed (Spat_T.pat ed (spats + ed.st.last_idx * 48))
      (Spat_T.patlen ed (spats + ed.st.last_idx * 48)) true (Win_T.w_cursor_addr ed.st.curwin)
