  let join41 i =
    if i = fail then clearopbeep ed oap
  in
  let join46 i =
    if i = fail then clearopbeep ed oap
  in
  match Cmdarg_T.nchar ed cap with
  | 1 (* Ctrl_A *) | 24 (* Ctrl_X *) ->
