        (Cmdarg_T.set_arg ed cap true_;
         Cmdarg_T.set_cmdchar ed cap (Cmdarg_T.nchar ed cap);
         Cmdarg_T.set_nchar ed cap nul;
         nv_addsub ed cap)
      else
        clearopbeep ed oap
  | 82 (* 'R' *) ->
      Cmdarg_T.set_arg ed cap true_;
      nv_Replace ed cap
  | 114 (* 'r' *) -> nv_vreplace ed cap
  | 38 (* '&' *) -> ignore (do_cmdline_cmd ed 164752 (* "%s//~/&" *))
  | 118 (* 'v' *) -> nv_gv_cmd ed cap
