          (if Cmdarg_T.nchar ed cap = Char.code '-' then
             - Cmdarg_T.count1 ed cap
           else
             Cmdarg_T.count1 ed cap) false false false
  | _ -> clearopbeep ed oap

let n_opencmd ed cap =
  if not (checkclearopq ed (Cmdarg_T.oap ed cap)) then
    (Buf_T.set_b_last_changedtick_i ed ed.st.curbuf (Buf_T.b_changedtick ed ed.st.curbuf);
     if u_save ed
          (Win_T.w_cursor_lnum ed ed.st.curwin -
           (if Cmdarg_T.cmdchar ed cap = Char.code 'O' then 1 else 0))
          (Win_T.w_cursor_lnum ed ed.st.curwin +
           (if Cmdarg_T.cmdchar ed cap = Char.code 'o' then 1 else 0)) &&
        open_line ed (if Cmdarg_T.cmdchar ed cap = Char.code 'O' then -1 else forward) 0 0 0 then
       (if vim_strchr ed (p_cpo ed) cpo_hash <> 0 then Cmdarg_T.set_count1 ed cap 1;
        invoke_edit ed cap false (Cmdarg_T.cmdchar ed cap) true))

let nv_dot ed cap =
  if not (checkclearopq ed (Cmdarg_T.oap ed cap)) then
    (if not (start_redo ed (Cmdarg_T.count0 ed cap)
           (ed.st.restart_edit <> 0 && not ed.st.arrow_used)) then
       clearopbeep ed (Cmdarg_T.oap ed cap))

let nv_redo_or_register ed cap =
  let join6 reg =
    ed.st.visual_select_reg <- (if valid_yank_reg ed reg true then reg else 0)
  in
  if ed.st.visual_select <> 0 && ed.st.visual_active then
    (ed.st.no_mapping <- ed.st.no_mapping + 1;
     ed.st.allow_keys <- ed.st.allow_keys + 1;
     let reg = plain_vgetc ed in
     ed.st.no_mapping <- ed.st.no_mapping - 1;
     ed.st.allow_keys <- ed.st.allow_keys - 1;
     if reg = Char.code '"' then join6 0 else join6 reg)
  else
    if not (checkclearopq ed (Cmdarg_T.oap ed cap)) then
      (u_redo ed (to_i32 (Cmdarg_T.count1 ed cap));
       Win_T.set_w_set_curswant ed ed.st.curwin true)

let u_undoline ed =
  let fr = frame_push ed 32 in
  let oldp = fr + 0 in
  if ed.st.undo_off then
    frame_pop ed fr
  else if Buf_T.b_u_line_ptr_ul_line ed ed.st.curbuf = 0 ||
     Buf_T.b_u_line_lnum ed ed.st.curbuf > Buf_T.b_ml_ml_line_count ed ed.st.curbuf then
    (beep_flush ed;
     frame_pop ed fr)
  else if not (u_savecommon ed (Buf_T.b_u_line_lnum ed ed.st.curbuf - 1)
        (Buf_T.b_u_line_lnum ed ed.st.curbuf + 1) 0 false) then
    frame_pop ed fr
  else if u_save_line ed oldp (Buf_T.b_u_line_lnum ed ed.st.curbuf) then
    (ignore (ml_replace_len ed (Buf_T.b_u_line_lnum ed ed.st.curbuf)
        (Buf_T.b_u_line_ptr_ul_line ed ed.st.curbuf)
        (to_i32 (Buf_T.b_u_line_ptr_ul_len ed ed.st.curbuf)) true false);
     changed_bytes ed (Buf_T.b_u_line_lnum ed ed.st.curbuf) 0;
     mem_copy ed (Buf_T.b_u_line_ptr_addr ed.st.curbuf) oldp 24;
     let t = Buf_T.b_u_line_colnr ed ed.st.curbuf in
     if Win_T.w_cursor_lnum ed ed.st.curwin = Buf_T.b_u_line_lnum ed ed.st.curbuf then
       Buf_T.set_b_u_line_colnr ed ed.st.curbuf (Win_T.w_cursor_col ed ed.st.curwin);
     Win_T.set_w_cursor_col ed ed.st.curwin t;
     Win_T.set_w_cursor_lnum ed ed.st.curwin (Buf_T.b_u_line_lnum ed ed.st.curbuf);
     check_cursor_col ed;
     frame_pop ed fr)
  else
    (do_outofmem_msg ed 0;
     frame_pop ed fr)

let nv_Undo ed cap =
  if Oparg_T.op_type ed (Cmdarg_T.oap ed cap) = op_upper || ed.st.visual_active then
    (Cmdarg_T.set_cmdchar ed cap (Char.code 'g');
     Cmdarg_T.set_nchar ed cap (Char.code 'U');
     nv_operator ed cap)
  else
    if not (checkclearopq ed (Cmdarg_T.oap ed cap)) then
      (u_undoline ed;
       Win_T.set_w_set_curswant ed ed.st.curwin true)

let nv_tilde ed cap =
  if p_to ed = 0 &&
     not ed.st.visual_active &&
     Oparg_T.op_type ed (Cmdarg_T.oap ed cap) <> op_tilde' then
    n_swapchar ed cap
  else
    nv_operator ed cap

let nv_pipe ed cap =
  Oparg_T.set_motion_type ed (Cmdarg_T.oap ed cap) mchar;
  Oparg_T.set_inclusive ed (Cmdarg_T.oap ed cap) false_;
  Win_T.set_w_cursor_col ed ed.st.curwin 0;
  Win_T.set_w_cursor_coladd ed ed.st.curwin 0;
  if Cmdarg_T.count0 ed cap > 0 then
    (ignore (coladvance ed (to_i32 (Cmdarg_T.count0 ed cap - 1)));
     Win_T.set_w_curswant ed ed.st.curwin (to_i32 (Cmdarg_T.count0 ed cap - 1)))
  else
    Win_T.set_w_curswant ed ed.st.curwin 0;
  Win_T.set_w_set_curswant ed ed.st.curwin false;
  adjust_skipcol ed

let nv_home ed cap =
  if mod_mask ed land mod_mask_ctrl = 0 then
    (Cmdarg_T.set_count0 ed cap 1;
     nv_pipe ed cap)
  else
    nv_goto ed cap;
  ed.st.ins_at_eol <- false

let nv_beginline ed cap =
  Oparg_T.set_motion_type ed (Cmdarg_T.oap ed cap) mchar;
  Oparg_T.set_inclusive ed (Cmdarg_T.oap ed cap) false_;
  beginline ed (Cmdarg_T.arg ed cap);
  ed.st.ins_at_eol <- false

let nv_select ed cap =
  if ed.st.visual_active then
    (ed.st.visual_select <- true_;
     ed.st.visual_select_reg <- 0)
  else
    if ed.st.visual_reselect then
      (Cmdarg_T.set_nchar ed cap (Char.code 'v');
       Cmdarg_T.set_arg ed cap true_;
       nv_g_cmd ed cap)

let nv_normal ed cap =
  if Cmdarg_T.nchar ed cap = ctrl_n || Cmdarg_T.nchar ed cap = ctrl_g then
    (clearop ed (Cmdarg_T.oap ed cap);
     if ed.st.restart_edit <> 0 && ed.st.mode_displayed then ed.st.clear_cmdline <- true;
     ed.st.restart_edit <- 0;
     if ed.st.visual_active then
       (end_visual_mode ed;
        redraw_curbuf_later ed upd_inverted);
     if Cmdarg_T.nchar ed cap = ctrl_g && p_im ed <> 0 then ed.st.restart_edit <- Char.code 'a')
  else
    clearopbeep ed (Cmdarg_T.oap ed cap)

let anyBufIsChanged ed =
  bufIsChanged ed ed.st.curbuf

let nv_esc ed cap =
  let no_reason =
    Oparg_T.op_type ed (Cmdarg_T.oap ed cap) = op_nop &&
    Cmdarg_T.opcount ed cap = 0 &&
    Cmdarg_T.count0 ed cap = 0 &&
    Oparg_T.regname ed (Cmdarg_T.oap ed cap) = 0 &&
    p_im ed = 0
  in
  let join9 () =
    if ed.st.visual_active then
      (end_visual_mode ed;
       check_cursor_col ed;
       Win_T.set_w_set_curswant ed ed.st.curwin true;
       redraw_curbuf_later ed upd_inverted)
    else
      if no_reason then vim_beep ed bo_esc;
    clearop ed (Cmdarg_T.oap ed cap);
    if ed.st.restart_edit = 0 && goto_im ed && ed.st.ex_normal_busy = 0 then
      ed.st.restart_edit <- Char.code 'a'
  in
  let join5 () =
    if ed.st.restart_edit <> 0 then ed.st.redraw_mode <- true;
    if p_im ed = 0 then ed.st.restart_edit <- 0;
    join9 ()
  in
  if Cmdarg_T.arg ed cap = 0 then
    join9 ()
  else if ed.st.restart_edit = 0 && not ed.st.visual_active && no_reason then
    (if anyBufIsChanged ed = 0 then
       (ignore (msg ed 164826 (* "Type  :qa  and press <Enter> to exit Vim" *));
        join5 ())
     else
       (ignore (msg ed
           164760 (* "Type  :qa!  and press <Enter> to abandon all changes and exit Vim" *));
        join5 ()))
  else
    join5 ()

let stuff_yank ed regname p =
  if regname <> 0 && not (valid_yank_reg ed regname true) then
    false
  else if regname = Char.code '_' then
    true
  else
    let plen = musl_strlen ed p in
    ignore (get_yank_register ed regname true_);
    if ed.st.y_append && Yankreg_T.y_array ed ed.st.y_current <> 0 then
      (let pp =
         Yankreg_T.y_array ed ed.st.y_current + (Yankreg_T.y_size ed ed.st.y_current - 1) * 16
       in
       let tmplen = String_T.length ed pp + plen in
       let tmp = alloc ed (tmplen + 1) in
       ignore (musl_strcpy ed tmp (String_T.string ed pp));
       ignore (musl_strcpy ed (tmp + String_T.length ed pp) p);
       String_T.set_string ed pp tmp;
       String_T.set_length ed pp tmplen;
       true)
    else
      (free_yank_all ed;
       let r1 = ed.st.y_current in
       Yankreg_T.set_y_array ed r1 (alloc ed 16);
       String_T.set_string ed (Yankreg_T.y_array ed ed.st.y_current) p;
       String_T.set_length ed (Yankreg_T.y_array ed ed.st.y_current) plen;
       Yankreg_T.set_y_size ed ed.st.y_current 1;
       Yankreg_T.set_y_type ed ed.st.y_current mchar;
       true)

let do_record ed c =
  let join7 retval =
    retval
  in
  if ed.st.reg_recording = 0 then
    (if c < 0 ||
        not (ascii_isupper c || ascii_islower c || ascii_isdigit c) && c <> Char.code '"' then
       join7 false
     else
       (ed.st.reg_recording <- c;
        ignore (showmode ed);
        ed.st.do_record__regname <- c;
        join7 true))
  else
    (ed.st.reg_recording <- 0;
     ignore (msg ed 162263 (* "" *));
     let p = get_recorded ed in
     if p = 0 then
       join7 false
     else
       (ignore (vim_unescape_csi ed p);
        let old_y_previous = ed.st.y_previous in
        let old_y_current = ed.st.y_current in
        let retval = stuff_yank ed ed.st.do_record__regname p in
        ed.st.y_previous <- old_y_previous;
        ed.st.y_current <- old_y_current;
        join7 retval))

let nv_record ed cap =
  if not (checkclearop ed (Cmdarg_T.oap ed cap)) then
    (if ed.st.reg_executing = 0 && not (do_record ed (Cmdarg_T.nchar ed cap)) then
