let get_encoded_char_adv ed p =
  let s = ld_ptr ed p in
  if ld_char ed s = '\\' &&
     (ld_char ed (s + 1) = 'x' || ld_char ed (s + 1) = 'u' || ld_char ed (s + 1) = 'U') then
    (let rec loop3 num bytes =
       if bytes > 0 then
         (st_ptr ed p (ld_ptr ed p + 2);
          let n = hexhex2nr ed (ld_ptr ed p) in
          if n < 0 then 0 else loop3 (num * 256 + n) (bytes - 1))
       else
         (st_ptr ed p (ld_ptr ed p + 2);
          to_i32 num)
     in
     loop3 0
       (match ld_char ed (s + 1) with
        | 'x' -> 1
        | 'u' -> 2
        | _ -> 4))
  else
    mb_ptr2char_adv ed p

