         (if Mparm_T.n_commands ed parmp >= max_arg_cmds then mainerr ed me_extra_cmd 0;
          if ld_s8 ed (ld_ptr ed argv + 1) = nul then
            (let t1 = Mparm_T.n_commands ed parmp in
